// PowerShell hands back one JSON object per line. NDJSON rather than one big
// array so a truncated scan fails on the line it died on instead of making the
// whole manifest unparseable.
const stdout = $input.first().json.stdout || '';

const files = [];
const bad = [];

for (const line of stdout.split(/\r?\n/)) {
  const trimmed = line.trim();
  if (!trimmed) continue;
  try {
    const row = JSON.parse(trimmed);
    if (row && row.name && row.sha256) files.push(row);
  } catch (e) {
    bad.push(trimmed.slice(0, 200));
  }
}

if (bad.length) {
  throw new Error(`${bad.length} unparseable manifest line(s). First: ${bad[0]}`);
}

if (!files.length) {
  throw new Error('The scan found no images. Check workDir points at the extracted folder.');
}

// One item per BATCH, not per file: /api/ingest/plan answers up to 500 files in
// a single round trip, so 10,000 photos cost 20 requests instead of 10,000.
const size = $('Settings').first().json.manifestSize;
const batches = [];

for (let i = 0; i < files.length; i += size) {
  batches.push({
    json: {
      batch: $('Settings').first().json.batch,
      files: files.slice(i, i + size),
      part: batches.length + 1,
      totalFiles: files.length,
    },
  });
}

return batches;

// Flatten every batch's verdict into one item per file worth uploading, and
// keep the skips so the run can report WHY 400 photos never moved.
const settings = $('Settings').first().json;

const accept = [];
const skipped = {};
const unknownSkus = {};

for (const item of $input.all()) {
  for (const row of item.json.accept || []) {
    accept.push({
      json: {
        ...row,
        batch: settings.batch,
        // Absolute path for the read node. The manifest name is relative to
        // workDir, which is exactly what the server matches SKUs against.
        path: settings.workDir.replace(/[\\/]+$/, '') + '\\' + row.name.replace(/\//g, '\\'),
      },
    });
  }

  for (const row of item.json.skip || []) {
    skipped[row.reason] = (skipped[row.reason] || 0) + 1;
    if (row.reason === 'unknown_sku') {
      const key = (row.tried || [row.sku]).join(' | ');
      unknownSkus[key] = (unknownSkus[key] || 0) + 1;
    }
  }
}

// Stash the skip tally where the final summary can reach it.
const staticData = $getWorkflowStaticData('global');
staticData.lastSkips = skipped;
staticData.lastUnknownSkus = unknownSkus;

if (!accept.length) {
  // Not an error: a re-run with nothing new is the expected happy path.
  return [{ json: { nothingToUpload: true, skipped, unknownSkus } }];
}

return accept;

// Every item that went round the loop lands here once the loop is done.
const staticData = $getWorkflowStaticData('global');

const tally = { stored: 0, duplicate: 0, unknown_sku: 0, hash_mismatch: 0, failed: 0 };
const failures = [];

for (const item of $input.all()) {
  const status = item.json?.body?.status;
  const code = item.json?.statusCode;

  if (status && tally[status] !== undefined) {
    tally[status]++;
  } else if (code && code >= 200 && code < 300) {
    tally.stored++;
  } else {
    tally.failed++;
    if (failures.length < 20) {
      failures.push({
        file: item.json?.body?.sku ?? item.json?.error ?? 'unknown',
        statusCode: code ?? null,
        message: item.json?.body?.message ?? item.json?.error?.message ?? null,
      });
    }
  }
}

return [{
  json: {
    batch: $('Settings').first().json.batch,
    uploads: tally,
    skippedByPlan: staticData.lastSkips || {},
    unknownSkus: staticData.lastUnknownSkus || {},
    firstFailures: failures,
  },
}];

// Merge what n8n saw with what the catalogue actually holds.
const report = $input.first().json;
const summary = $('Summarise run').first().json;

return [{
  json: {
    batch: summary.batch,
    catalogue: {
      products: report.products,
      images: report.images,
    },
    uploads: summary.uploads,
    skippedByPlan: summary.skippedByPlan,
    // The actionable list: SKU readings that matched nothing. Each key shows
    // every interpretation tried, best first, so a wrong pattern in
    // config/ingest.php is obvious rather than mysterious.
    unknownSkus: summary.unknownSkus,
    firstFailures: summary.firstFailures,
  },
}];

// Reached when /plan accepted nothing — normally a re-run where every photo
// is already in the catalogue. Worth reporting, not worth failing.
return [{
  json: {
    batch: $('Settings').first().json.batch,
    result: 'nothing new to upload',
    skippedByPlan: $json.skipped || {},
    unknownSkus: $json.unknownSkus || {},
  },
}];
